import os, re, json

# Fix the transform function and test
def transform(grid):
    """Replace 2s with values from symmetric position row (rows-1-r)."""
    rows = len(grid)
    output = [row[:] for row in grid]
    rows_minus_1 = rows - 1

    for r in range(rows):
        for c in range(rows):
            if grid[r][c] == 2:
                new_r = rows_minus_1 - r
                # If the symmetric position also has 2, look for another source
                if new_r == r or grid[new_r][c] == 2:
                    # Find another row that has a non-2 value at this column
                    for other_r in range(rows):
                        if other_r != r and grid[other_r][c] != 2:
                            output[r][c] = grid[other_r][c]
                            break
                else:
                    output[r][c] = grid[new_r][c]
    return output

